INSERT INTO catalog (key, version, json, updated_at) VALUES ('skills', 1, '{"version":1,"skills":[{"id":"multi_jump","name":"Multi-Jump","desc":"Leap multiple times mid-air to reach high ledges and evade fire","price":2500,"icon":"👟","max_stage":3,"stages":[{"stage":1,"cost":2500,"name":"Double Jump","desc":"2 Jumps total (1 Ground + 1 Mid-Air)"},{"stage":2,"cost":5000,"name":"Triple Jump","desc":"3 Jumps total (1 Ground + 2 Mid-Air)"},{"stage":3,"cost":10000,"name":"Quad Jump","desc":"4 Jumps total (1 Ground + 3 Mid-Air - Acrobatic)"}]},{"id":"spawn_hp","name":"Spawn HP Boost","desc":"Begin every round with enhanced vitality above standard 100 HP","price":2000,"icon":"❤️","max_stage":3,"stages":[{"stage":1,"cost":2000,"name":"Vitality I","desc":"+10 Max HP on spawn (110 HP)"},{"stage":2,"cost":4500,"name":"Vitality II","desc":"+20 Max HP on spawn (120 HP)"},{"stage":3,"cost":8000,"name":"Vitality III","desc":"+30 Max HP on spawn (130 HP Titan)"}]},{"id":"spawn_armor","name":"Spawn Armor Boost","desc":"Spawn automatically equipped with military body armor & helmet","price":1500,"icon":"🛡️","max_stage":3,"stages":[{"stage":1,"cost":1500,"name":"Reinforced Kevlar","desc":"+50 Kevlar Armor on spawn"},{"stage":2,"cost":3500,"name":"Assault Suit","desc":"+100 Kevlar & Helmet on spawn"},{"stage":3,"cost":6000,"name":"Juggernaut Vest","desc":"+125 Reinforced Armor & Helmet on spawn"}]},{"id":"vampire","name":"Vampire Lifesteal","desc":"Extract health directly from fallen opponents upon every frag","price":2500,"icon":"🩸","max_stage":3,"stages":[{"stage":1,"cost":2500,"name":"Blood Sip","desc":"+10 HP restored per kill"},{"stage":2,"cost":5000,"name":"Blood Feast","desc":"+20 HP per kill (+30 HP on Headshot)"},{"stage":3,"cost":8500,"name":"Vampiric Lord","desc":"+30 HP per kill (+45 HP on Headshot)"}]},{"id":"nimble","name":"Nimble Agility","desc":"Passive movement speed enhancement for faster rotations & flanking","price":1500,"icon":"⚡","max_stage":3,"stages":[{"stage":1,"cost":1500,"name":"Swiftness I","desc":"+5% Permanent Movement Speed"},{"stage":2,"cost":3500,"name":"Swiftness II","desc":"+10% Permanent Movement Speed"},{"stage":3,"cost":6500,"name":"Swiftness III","desc":"+15% Permanent Movement Speed"}]},{"id":"featherfall","name":"Featherfall","desc":"Absorbs kinetic impact from severe heights and cliff drops","price":1000,"icon":"🪶","max_stage":3,"stages":[{"stage":1,"cost":1000,"name":"Cushion","desc":"35% Fall Damage Reduction"},{"stage":2,"cost":2500,"name":"Shock Absorber","desc":"70% Fall Damage Reduction"},{"stage":3,"cost":5000,"name":"Zero-G Boots","desc":"100% Fall Damage Immunity (0 Damage)"}]},{"id":"healthnade","name":"HealthNade","desc":"Transforms your smoke grenade into a high-potency restorative vapor","price":2500,"icon":"🧪","max_stage":2,"stages":[{"stage":1,"cost":2500,"name":"Medic Smoke","desc":"Smoke grenade emits 250-unit healing zone restoring +35 HP to nearby allies"},{"stage":2,"cost":5000,"name":"Nano Mist","desc":"Enhanced nanotech vapor heals +70 HP and repairs +35 Armor"}]},{"id":"fast_sniper","name":"Fast Sniper","desc":"Accelerates bolt-action chambering and weapon draw speed on sniper rifles","price":2000,"icon":"🎯","max_stage":2,"stages":[{"stage":1,"cost":2000,"name":"Quick Bolt","desc":"15% faster bolt cycle & re-zoom on AWP/Scout"},{"stage":2,"cost":4500,"name":"Master Marksman","desc":"30% faster bolt cycle & instant weapon switch"}]},{"id":"revive","name":"Combat Medic","desc":"Resurrect dead teammates right where they fell using the CPR defibrillator","price":3000,"icon":"💉","max_stage":2,"stages":[{"stage":1,"cost":3000,"name":"Field Medic","desc":"Revive teammates within 3.0 seconds"},{"stage":2,"cost":6000,"name":"Trauma Specialist","desc":"Rapid Revive within 1.5 seconds"}]},{"id":"laststand","name":"Last Stand","desc":"Emergency adrenaline surge defying death when taking fatal damage","price":3500,"icon":"🛡️","max_stage":2,"stages":[{"stage":1,"cost":3500,"name":"Second Wind","d